-- reports/source-by-url
-- An existing source row for a news link (it may not be attached to a crash yet).
--
-- Parameters, with the example values used to render this file:
--   $1 = "example.com/news/1"
--   $2 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/reports.ts. Do not edit by hand.

select "id"
from "sources"
where "sources"."normalized_url" = $1
limit $2;
